-- Multiple PROJECTION POLICY statements
CREATE PROJECTION POLICY policy1 
  AS () 
  RETURNS PROJECTION_CONSTRAINT 
  -> PROJECTION_CONSTRAINT(ALLOW => true);
CREATE PROJECTION POLICY policy2 
  AS () 
  RETURNS PROJECTION_CONSTRAINT 
  -> PROJECTION_CONSTRAINT(ALLOW => false);
ALTER PROJECTION POLICY policy1 
  SET BODY -> PROJECTION_CONSTRAINT(ALLOW => false, ENFORCEMENT => 'NULLIFY');
ALTER PROJECTION POLICY IF EXISTS policy2 
  SET TAG env = 'prod', owner = 'security';
ALTER PROJECTION POLICY policy1 
  RENAME TO policy1_renamed;
DROP PROJECTION POLICY policy2;